CREATE TABLE IF NOT EXISTS "customer_balance_site_accounts" ("id" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL PRIMARY KEY, "site_id" INTEGER NOT NULL, "username" TEXT NOT NULL, "password_cipher" TEXT NOT NULL, "access_token" TEXT, "platform_user_id" TEXT, "token_expires_at" INTEGER, "last_synced_at" TEXT, "last_error" TEXT, "created_at" TEXT DEFAULT to_char(timezone('UTC', CURRENT_TIMESTAMP), 'YYYY-MM-DD HH24:MI:SS'), "updated_at" TEXT DEFAULT to_char(timezone('UTC', CURRENT_TIMESTAMP), 'YYYY-MM-DD HH24:MI:SS'), FOREIGN KEY ("site_id") REFERENCES "sites"("id") ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS "customer_balance_snapshots" ("id" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL PRIMARY KEY, "site_account_id" INTEGER NOT NULL, "site_id" INTEGER NOT NULL, "platform" TEXT NOT NULL, "total_users" INTEGER NOT NULL DEFAULT 0, "active_users" INTEGER NOT NULL DEFAULT 0, "total_balance" DOUBLE PRECISION NOT NULL DEFAULT 0, "low_balance_users" INTEGER NOT NULL DEFAULT 0, "negative_balance_users" INTEGER NOT NULL DEFAULT 0, "zero_balance_users" INTEGER NOT NULL DEFAULT 0, "raw_payload" TEXT, "created_at" TEXT DEFAULT to_char(timezone('UTC', CURRENT_TIMESTAMP), 'YYYY-MM-DD HH24:MI:SS'), FOREIGN KEY ("site_account_id") REFERENCES "customer_balance_site_accounts"("id") ON DELETE CASCADE, FOREIGN KEY ("site_id") REFERENCES "sites"("id") ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS "customer_balance_snapshot_users" ("id" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL PRIMARY KEY, "snapshot_id" INTEGER NOT NULL, "upstream_user_id" TEXT NOT NULL, "username" TEXT, "email" TEXT, "display_name" TEXT, "role" TEXT, "status" TEXT, "balance" DOUBLE PRECISION NOT NULL DEFAULT 0, "used" DOUBLE PRECISION NOT NULL DEFAULT 0, "quota" DOUBLE PRECISION NOT NULL DEFAULT 0, "group_name" TEXT, "created_at" TEXT, "last_active_at" TEXT, "raw_payload" TEXT, FOREIGN KEY ("snapshot_id") REFERENCES "customer_balance_snapshots"("id") ON DELETE CASCADE);
CREATE UNIQUE INDEX "customer_balance_site_accounts_site_unique" ON "customer_balance_site_accounts" ("site_id");
CREATE UNIQUE INDEX "customer_balance_snapshot_users_snapshot_user_unique" ON "customer_balance_snapshot_users" ("snapshot_id", "upstream_user_id");
CREATE INDEX "customer_balance_site_accounts_last_synced_at_idx" ON "customer_balance_site_accounts" ("last_synced_at");
CREATE INDEX "customer_balance_site_accounts_site_id_idx" ON "customer_balance_site_accounts" ("site_id");
CREATE INDEX "customer_balance_snapshot_users_snapshot_balance_idx" ON "customer_balance_snapshot_users" ("snapshot_id", "balance");
CREATE INDEX "customer_balance_snapshot_users_snapshot_status_idx" ON "customer_balance_snapshot_users" ("snapshot_id", "status");
CREATE INDEX "customer_balance_snapshots_account_created_at_idx" ON "customer_balance_snapshots" ("site_account_id", "created_at");
CREATE INDEX "customer_balance_snapshots_site_created_at_idx" ON "customer_balance_snapshots" ("site_id", "created_at");
